class Kont {
  readonly id: number;
  private sòld: number = 0;
  constructor(id: number) {
    this.id = id;
  }
  depoze(montan: number): void {
    if (montan > 0) this.sòld += montan;
  }
  getSòld(): number {
    return this.sòld;
  }
}
const k = new Kont(1);
// k.sòld = 999; // ERÈ: private!

function jwenn<T, K extends keyof T>(obj: T, kle: K): T[K] {
  return obj[kle];
}
const itilizatè = { non: "Mariz", laj: 28 };
const non = jwenn(itilizatè, "non"); // string
// jwenn(itilizatè, "adrès"); // ERÈ: "adrès" pa yon kle!
type KleItilizatè = keyof typeof itilizatè;

interface Itilizatè {
  id: number;
  non: string;
  modpas: string;
}
type Piblik = Omit<Itilizatè, "modpas">;
// Piblik = { id: number; non: string }
